    if (str == null && prefix == null) {
        return true;
    }

    // If either str or prefix are null, return false
    if (str == null || prefix == null) {
        return false;
    }

    // If ignoreCase is true, convert both strings to lowercase before checking
    if (ignoreCase) {
        str = str.toLowerCase();
        prefix = prefix.toLowerCase();
    }

    // Check if str starts with prefix
    return str.startsWith(prefix);
}

