public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAncodeTimeRange>timeRanges) throws IOException {
   List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
   try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
      String line;
      while ((line = reader.readLine()) != null) {
         try {
            ThreadSnapshot threadSnapshot = ThreadSnapshot.parseFromString(line);
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
               if (threadSnapshot.getTimestamp() >= timeRange.start && threadSnapshot.getTimestamp() <= timeRange.end) {
                  threadSnapshots.add(threadSnapshot);
                  break;
               }
            }
         } catch (RuntimeException e) {
            System.err.println("Failed to parse line: " + line);
         }
      }
   }
   return threadSnapshots;
}
